# Scripts for the four long-form Vox videos of 28 Sep 2026 (from the verified articles) and their shorts.
# Each beat: key, ch, say (spoken; numbers as words), cap (display; numerals), scene (engine spec).
# "at" values are phrases from `say` (optionally "phrase|offsetFrames"); the build step checks they exist.

def T(ch, key, say, cap, scene): return dict(ch=ch, key=key, say=say, cap=cap, scene=scene)
def title(ch, key, lines, say=None, red=False):
    return T(ch, key, say or f"Chapter {ch}. " + " ".join(lines).capitalize().rstrip(",") + ".", None, dict(type="title", lines=lines, red=red))

END_SAY = "This is educational research, not investment advice. Moat and Margin is not a SEBI registered research analyst or investment adviser."
END_CAP = "This is educational research, not investment advice. Moat & Margin is not a SEBI-registered Research Analyst or Investment Adviser."

